import React from 'react'
import { connect } from 'react-redux'
import moment from 'moment-timezone'
import {
  Card,
  Button,
  Upload,
  Icon,
  Spin,
  message,
  Row,
  Col,
  Select,
  Alert,
  DatePicker
} from 'antd'
import PropTypes from 'prop-types'

import { LayoutWrapper } from './index.style'
import UploadAction from '../../../redux/gocar/actions'

const { uploadGocarBulkExcel, getGocarFileTemplates, getGocarTemplateSample } = UploadAction

const { Dragger } = Upload
const { Option } = Select
const { MonthPicker } = DatePicker

class MainUpload extends React.Component {
  state = {
    percent: 0,
    updatePolicyUpload: false,
    addPayment: false,
    statusUploadFile: '',
    fileName: '',
    loadingPolicy: false,
    loadingPayment: false,
    dateString: '',
    paymentPart: ''
  }

  componentDidMount () {
    this.props.getGocarFileTemplates()
  }

  componentWillReceiveProps (nextProps) {
    const { GocarData } = nextProps
    if (GocarData) {
      this.setState({
        statusUploadFile: GocarData.status,
        loadingPolicy: false,
        loadingPayment: false
      })
    }
  }

  handleSelect (val) {
    const values = JSON.parse(val)
    this.setState({
      selectedTemplate: values
    })
  }

  handleMonthChange = (val, monthYear) => {
    const dateString = monthYear
    this.setState({ dateString })
  }

  handlePartChange = (paymentPart) => {
    this.setState({ paymentPart })
  }

  resetUploader = identifier => {
    this.setState({ [identifier]: false })
  }

  customRequest = ({ file }) => {
    const { selectedTemplate, dateString, paymentPart } = this.state
    const { templateList } = this.props
    const defaultValue = templateList.length === 1 ? templateList[0].id : false
    const templateId = selectedTemplate.id || defaultValue
    const { type } = file
    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'text/csv'].includes(type)) {
      const formData = new FormData()
      formData.append('file', file)
      if (dateString !== '') {
        const txnDate = paymentPart === 'part1' ? '15' : moment(dateString).endOf('month').format('DD')
        formData.append('dateString', dateString + '-' + txnDate)
      }
      this.props.uploadGocarBulkExcel({ body: formData, params: { templateId } })
    } else {
      message.error('Incorrect file type, please upload only .xlsx/.csv')
    }
  }

  render () {
    const {
      selectedTemplate = {},
      dateString,
      paymentPart
    } = this.state
    const {
      templatesLoading,
      templatesError,
      templateList,
      templateListMessage,
      uploadGocarBulkExcelLoading,
      uploadGocarBulkExcelError,
      uploadGocarBulkExcelMessage,
      getFileTemplateSampleLoading,
      getFileTemplateSampleError,
      getFileTemplateSampleMessage
    } = this.props
    const defaultValue = templateList.length === 1 ? templateList[0].id : false

    return (
      <LayoutWrapper>
        <Card style={{ width: '100%' }}>
          <Spin tip='Uploading...' spinning={!!templatesLoading || !!uploadGocarBulkExcelLoading}>
            <Row>
              <Col xs={{ span: 24 }} lg={{ span: 8, offset: 13 }}>
                {
                  !templatesLoading && (
                    <Select
                      showSearch
                      style={{ width: '100%' }}
                      placeholder='Select an operation'
                      onSelect={val => this.handleSelect(val)}
                      value={(JSON.stringify(selectedTemplate) !== '{}' && JSON.stringify(selectedTemplate)) || defaultValue}
                    >
                      {
                        templateList.map(({ id, name, operation, product_code: productCode }) => {
                          return (
                            <Option key={id} value={JSON.stringify({ id, name })}>{name || operation || productCode}</Option>
                          )
                        }
                        )
                      }
                    </Select>
                  )
                }
              </Col>
              <Col xs={{ span: 24 }} lg={{ span: 3 }}>
                <Button
                  loading={getFileTemplateSampleLoading}
                  disabled={!selectedTemplate.id || uploadGocarBulkExcelLoading}
                  onClick={() => this.props.getGocarTemplateSample({ params: { templateId: selectedTemplate.id } })}
                  style={{ marginLeft: '5px' }}
                >
                  Download Sample
                </Button>
              </Col>
            </Row>
            <Row type='flex'>
              <Col className='month-selector'>
                {
                  (selectedTemplate.name === 'UPDATE_GOCAR_SIMPLE_PAYMENT_DETAILS' || selectedTemplate.name === 'UPDATE_GOCAR_COMPLETE_PAYMENT_DETAILS') &&
                  <MonthPicker
                    placeholder='Select Month'
                    onChange={this.handleMonthChange}
                  />
                }
              </Col>
              <Col className='month-selector' span={6}>
                {
                  selectedTemplate.name === 'UPDATE_GOCAR_SIMPLE_PAYMENT_DETAILS' &&
                  <Select
                    className='select-style'
                    placeholder='Select Payment Part'
                    onChange={this.handlePartChange}
                  >
                    <Option value='part1'>Part 1 - Week 1,2</Option>
                    <Option value='part2'>Part 2 - Week 3,4</Option>
                  </Select>
                }
              </Col>
            </Row>
            <Row style={{ marginTop: '10px' }}>
              {
                !templatesLoading && templateListMessage && templatesError && (
                  <Alert style={{ marginBottom: '10px', textAlign: 'center' }} message={templateListMessage} type='error' />
                )
              }
              {
                !getFileTemplateSampleLoading && getFileTemplateSampleMessage && getFileTemplateSampleError && (
                  <Alert style={{ marginBottom: '10px', textAlign: 'center' }} message={getFileTemplateSampleMessage} type='error' />
                )
              }
              {
                !uploadGocarBulkExcelLoading && uploadGocarBulkExcelMessage && (
                  <Alert style={{ marginBottom: '10px', textAlign: 'center' }} message={uploadGocarBulkExcelError ? 'Failed, please re-upload the file' : (<div>Your Data is successfully Uploaded</div>)} type={uploadGocarBulkExcelError ? 'error' : 'success'} />
                )
              }
              <Dragger
                disabled={
                  (!defaultValue && !selectedTemplate.id) ||
                  !!uploadGocarBulkExcelLoading ||
                  ((selectedTemplate.name === 'UPDATE_GOCAR_SIMPLE_PAYMENT_DETAILS' || selectedTemplate.name === 'UPDATE_GOCAR_COMPLETE_PAYMENT_DETAILS') && dateString === '') ||
                  ((selectedTemplate.name === 'UPDATE_GOCAR_SIMPLE_PAYMENT_DETAILS') && (dateString === '' || paymentPart === ''))
                }
                name='file'
                showUploadList={false}
                multiple={false}
                customRequest={val => this.customRequest(val)}
              >
                {(!defaultValue && !selectedTemplate) ? (
                  <div>
                    <p className='ant-upload-drag-icon'>
                      <Icon type='info-circle' />
                    </p>
                    <p className='ant-upload-text'>Select a template to upload</p>
                  </div>
                ) : (
                  <div>
                    <p className='ant-upload-drag-icon'>
                      <Icon type='inbox' />
                    </p>
                    <p className='ant-upload-text'>Click or drag file to this area to upload</p>
                  </div>
                )}
              </Dragger>
            </Row>
          </Spin>
        </Card>
      </LayoutWrapper>
    )
  }
}

MainUpload.propTypes = {
  templateList: PropTypes.array.isRequired
}

MainUpload.defaultProps = {
  templateList: []
}

export default connect(
  state => ({
    templatesLoading: state.Loading.GET_GOCAR_FILE_TEMPLATES,
    templatesError: state.Error.GET_GOCAR_FILE_TEMPLATES,
    templateList: state.Gocar.templateList,
    templateListMessage: state.Gocar.templateListMessage,
    uploadGocarBulkExcelLoading: state.Loading.UPLOAD_GOCAR_BULK_EXCEL,
    uploadGocarBulkExcelError: state.Error.UPLOAD_GOCAR_BULK_EXCEL,
    uploadGocarBulkExcelMessage: state.Gocar.uploadGocarBulkExcelMessage,
    getFileTemplateSampleLoading: state.Loading.GET_GOCAR_TEMPLATE_SAMPLE,
    getFileTemplateSampleError: state.Error.GET_GOCAR_TEMPLATE_SAMPLE,
    getFileTemplateSampleMessage: state.Gocar.getFileTemplateSampleMessage
  }),
  {
    uploadGocarBulkExcel,
    getGocarFileTemplates,
    getGocarTemplateSample
  }
)(MainUpload)
